hero_layout.css:
.hero {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: radial-gradient(ellipse at 50% 0%, rgba(108,99,255,0.3) 0%, transparent 70%),
              radial-gradient(ellipse at 80% 80%, rgba(255,99,108,0.15) 0%, transparent 50%),
              #0A0A0F;
  padding: 2rem;
}
.hero-content {
  text-align: center;
  max-width: 720px;
}
.hero-title {
  font-size: clamp(2.5rem, 6vw, 5rem);
  font-weight: 800;
  letter-spacing: -0.04em;
  line-height: 1.05;
  color: #fff;
  margin-bottom: 1.5rem;
}
.hero-sub {
  font-size: 1.25rem;
  color: rgba(255,255,255,0.6);
  line-height: 1.7;
  margin-bottom: 2.5rem;
}
.hero-cta { display: flex; gap: 1rem; justify-content: center; flex-wrap: wrap; }
.btn-primary {
  padding: 0.875rem 2rem;
  background: #6C63FF;
  color: #fff;
  border-radius: 8px;
  font-weight: 600;
  text-decoration: none;
  transition: opacity 0.2s;
}
.btn-primary:hover { opacity: 0.85; }
.btn-ghost {
  padding: 0.875rem 2rem;
  border: 1px solid rgba(255,255,255,0.2);
  color: rgba(255,255,255,0.8);
  border-radius: 8px;
  font-weight: 500;
  text-decoration: none;
}

recommended_component.css:
.btn-glow {
  padding: 0.875rem 2rem;
  background: linear-gradient(135deg, #6C63FF, #A855F7);
  color: #fff;
  font-weight: 600;
  font-size: 0.95rem;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  position: relative;
  transition: opacity 0.2s, transform 0.2s;
}
.btn-glow::before {
  content: '';
  position: absolute;
  inset: -2px;
  background: linear-gradient(135deg, #6C63FF, #A855F7);
  border-radius: 10px;
  z-index: -1;
  opacity: 0;
  filter: blur(12px);
  transition: opacity 0.3s;
}
.btn-glow:hover { transform: translateY(-1px); }
.btn-glow:hover::before { opacity: 0.7; }
.btn-glow:active { transform: translateY(0); }
